import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import {ProjectDock} from '../../../src/ui/ProjectDock';
import {documentSchema,validateDocument} from '../../../src/core/model';
const project=validateDocument(documentSchema.parse({schemaVersion:1,id:'dock-browser',title:'Synthetic project dock',rootViewId:'overview',nodes:[{id:'source',label:'Supplied source',kind:'source',sourceIds:['contract']},{id:'process',label:'Review transformation',kind:'process',basis:'planned',sourceIds:['contract']}],edges:[],views:[{id:'overview',title:'System overview',nodeIds:['source','process']},{id:'workflow',title:'Transformation workflow',nodeIds:['process']}],sources:[{id:'contract',title:'Source contract',location:'supplied/source.ts:1-4'}],story:[{title:'Inspect transformation',viewId:'workflow',nodeId:'process',narration:'Presented order, not execution.'}]}));
function Fixture(){const [view,setView]=useState('overview'),[selected,setSelected]=useState<string|null>(null),[step,setStep]=useState(-1),[tool,setTool]=useState('');return <><output aria-label="Current canonical navigation">{view}:{selected??'-'}:{step}</output><output aria-label="Opened existing tool">{tool}</output><ProjectDock project={project} audience="author" activeViewId={view} selectedNodeId={selected} storyIndex={step} onNavigate={(v,n)=>{setView(v);setSelected(n??null);}} onStory={i=>{const s=project.story[i];setView(s.viewId);setSelected(s.nodeId??null);setStep(i);}} tools={['comparison','work','variants','history','git']} onOpenTool={setTool}/></>;}
createRoot(document.getElementById('root')!).render(<Fixture/>);
